export function validMapPoint(point){return Boolean(point&&Number.isFinite(point.latitude)&&Math.abs(point.latitude)<=85.051129&&Number.isFinite(point.longitude)&&Math.abs(point.longitude)<=180&&Number.isFinite(point.accuracyMeters)&&point.accuracyMeters>=0&&point.accuracyMeters<=10000);}
export function accuracyArea(point){if(!validMapPoint(point))throw new Error('Invalid map position');const lat=point.latitude*Math.PI/180,lon=point.longitude*Math.PI/180,d=point.accuracyMeters/6371008.8,ring=[];for(let i=0;i<=64;i++){const a=i/64*2*Math.PI,p=Math.asin(Math.sin(lat)*Math.cos(d)+Math.cos(lat)*Math.sin(d)*Math.cos(a)),l=lon+Math.atan2(Math.sin(a)*Math.sin(d)*Math.cos(lat),Math.cos(d)-Math.sin(lat)*Math.sin(p));ring.push([l*180/Math.PI,p*180/Math.PI]);}return{type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[ring]}};}
